```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat seconds={} fetched={}", seconds, fetched);
        let notified = notifier::notify(&message);

        // ensures: notified == true. A refused notification cannot be reported
        // as a successful output, so it traps instead.
        if !notified {
            panic!("notifier refused the heartbeat message");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

I did not add the `aap:caps/state-rw@0.1.0` import or the `last-input` write. The graph definition still declares this node's grant as HTTPClient, Notifier, and Clock only, and the approval isn't reflected there yet. If the host doesn't link `state-rw` for this node, the component won't instantiate, and if it does, the node would be writing to a store its definition doesn't grant. Once the graph definition includes `state-rw`, adding the import and a `put("last-input", feed_url)` call before the return is a small change.

